-- public.gate_said(p_action text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.gate_said(p_action text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select case p_action
    when 'raise_portcullis' then 'Portcullis raised: all pass.'
    when 'lower_portcullis' then 'Portcullis lowered: nothing passes; still see-through.'
    when 'raise_drawbridge' then 'Drawbridge raised: nothing crosses.'
    else 'Drawbridge lowered: people and creatures'
      || case when (select d.carts from bridge_def d where d.id = 'draw') then ' and carts' else '' end || ' cross.'
  end
$function$
